def write_tests() -> None:
    TEST.write_text('''from __future__ import annotations\n\nimport pandas as pd\n\nfrom modules.deep_company_analysis.chapter3_auto import (\n    build_chapter3_assistant_draft,\n    evidence_quality_coverage,\n    extract_concentration_candidates,\n    research_gap_suggestions,\n)\n\n\ndef row(group: str, snippet: str, *, score: int = 60, url: str = "https://example.com") -> dict:\n    return {\n        "Nhóm thông tin": group,\n        "Tiêu đề": "Evidence",\n        "Nguồn/URL": url,\n        "Trích yếu": snippet,\n        "Điểm phù hợp": score,\n    }\n\n\ndef test_export_share_must_not_become_customer_concentration():\n    df = pd.DataFrame([row(\n        "Nguồn doanh nghiệp/IR | Q8",\n        "Với 80% doanh thu đến từ xuất khẩu, công ty phục vụ thị trường trong và ngoài nước.",\n    )])\n    assert extract_concentration_candidates(df) == []\n    quality = evidence_quality_coverage(df)\n    assert quality["eligible_fields"]["Q8 Concentration evidence"] is False\n\n\ndef test_named_customers_without_revenue_share_are_evidence_but_not_concentration_metric():\n    df = pd.DataFrame([row(\n        "BCTC/PDF chính thức | Q8",\n        "Các khoản phải thu khách hàng bao gồm Mitsubishi Corporation và ICL Specialty Products Inc.",\n    )])\n    assert extract_concentration_candidates(df) == []\n    assert evidence_quality_coverage(df)["eligible_fields"]["Q8 Concentration evidence"] is False\n\n\ndef test_customer_support_evidence_counts_for_q11_without_auto_judgement():\n    df = pd.DataFrame([row(\n        "Nguồn doanh nghiệp/IR | Q11",\n        "Mọi thắc mắc khách hàng liên hệ tổng đài tư vấn; công ty tiếp nhận và giải đáp thông tin cho khách hàng.",\n        url="https://dgcmall.vn/lien-he",\n    )])\n    quality = evidence_quality_coverage(df)\n    assert quality["eligible_fields"]["Q11 Customer-orientation evidence"] is True\n    draft = build_chapter3_assistant_draft(df)\n    assert draft["q11"]["customer_orientation_summary"]\n\n\ndef test_placeholder_links_do_not_inflate_quality_coverage():\n    df = pd.DataFrame([row(\n        "Nguồn công bố chính thức | Q14",\n        "Nguồn ưu tiên để kiểm tra DGC: mở link để đối chiếu với dữ liệu trong app.",\n    )])\n    quality = evidence_quality_coverage(df)\n    assert quality["eligible_fields"]["Q14 Replacement/disappearance evidence"] is False\n\n\ndef test_missing_metrics_generate_explicit_research_gaps():\n    quality = evidence_quality_coverage(pd.DataFrame())\n    gaps = research_gap_suggestions(quality)\n    assert any(text.startswith("Q8") for text in gaps)\n    assert any(text.startswith("Q10") for text in gaps)\n    assert any("Profit Relevance" in text for text in gaps)\n''', encoding="utf-8")


def patch_context() -> None:
    text = CONTEXT.read_text(encoding="utf-8")
    if "## Phase 3D — DGC final acceptance and implementation lock" in text:
        return
    text += '''\n\n---\n\n## Phase 3D — DGC final acceptance and implementation lock\n\nPhase 3D hardens evidence quality rather than trying to force 8/8 autofill. The implementation must distinguish **usable evidence** from mere search-result count.\n\nQuality rules:\n\n- Q8 counts as usable concentration evidence only when an explicit customer/major-customer percentage candidate is present; export/geographic/segment revenue never qualifies by itself.\n- Q10 counts as usable retention evidence only when an explicit retention/churn/renewal metric is found in a trusted source.\n- Q7/Q9/Q11/Q12/Q13/Q14 require substantive trusted evidence; generic source-directory placeholders do not count.\n- Customer-facing first-party sources may support Q9/Q11, but do not automatically prove strong customer orientation.\n- Research Assistant may generate **Research Gap suggestions**, but must not overwrite analyst Research Gaps.\n- Revenue Relevance / Profit Relevance remain optional analyst/evidence fields and are never auto-filled merely to improve completion.\n- An implementation can be locked even if DGC still has Unknown questions: `Unknown` represents a real evidence gap, not a software failure.\n\nDGC final acceptance requires:\n\n1. live evidence collection completes without critical engine error;\n2. all analyst-judgement autofill guardrails remain false;\n3. export share does not become customer concentration;\n4. customer names without explicit share do not become a fabricated concentration percentage;\n5. generic links/placeholders do not inflate Q13/Q14 coverage;\n6. missing Q8/Q10/Q11/Q13/Q14 evidence is surfaced as Research Gaps instead of invented conclusions;\n7. full Chapter 1–3 regression and unified-page smoke tests pass.\n'''
    CONTEXT.write_text(text, encoding="utf-8")


def main() -> None:
    patch_auto()
    patch_support()
    patch_e2e()
    write_tests()
    patch_context()
    print("Applied Chapter 3 Phase 3D evidence-quality and DGC acceptance hardening.")


if __name__ == "__main__":
    main()
